<template>
  <section class="alert-detail" v-loading="loading">
    <header class="page-heading"><h1>库存预警详情</h1><div><el-button icon="el-icon-arrow-left" @click="$router.push('/inventory/alerts')">返回预警列表</el-button><el-button v-if="!alert.purchase_request_id && alert.is_active" type="success" icon="el-icon-shopping-cart-2" @click="createRequest">生成采购需求</el-button><el-button v-else-if="alert.purchase_request_id" type="success" @click="openPurchaseRequest">{{ purchaseAction }}</el-button></div></header>
    <el-alert title="本预警基于实际可用库存计算产生；生成的采购需求仅为草稿，需人工审核后提交执行。" type="info" :closable="false" show-icon/>
    <section class="top-grid">
      <article class="card object"><h2><i class="el-icon-box"/>预警对象</h2><dl><dt>物料编码</dt><dd>{{ item.item_code || '-' }}</dd><dt>物料名称</dt><dd>{{ item.item_name || '-' }}</dd><dt>物料分类</dt><dd>{{ item.category && item.category.category_name || '-' }}</dd><dt>计量单位</dt><dd>{{ unit }}</dd></dl></article>
      <article class="card facts"><h2><i class="el-icon-data-analysis"/>当前库存事实</h2><div class="facts-body"><dl><dt>仓库</dt><dd>{{ warehouse.warehouse_name || '-' }}</dd><dt>在库数量</dt><dd>{{ number(alert.quantity_on_hand) }} {{ unit }}</dd><dt>已锁定 / 已预留</dt><dd>{{ number(alert.quantity_locked) }} {{ unit }}</dd><dt>不良 / 待处理</dt><dd>{{ number(alert.quantity_defective) }} {{ unit }}</dd></dl><div class="available"><span>可用库存</span><strong :class="severityClass">{{ number(alert.available_qty) }} {{ unit }}</strong></div></div></article>
      <article class="card state"><h2><i class="el-icon-bell"/>当前预警状态</h2><dl><dt>预警等级</dt><dd><el-tag size="mini" :type="tagType">{{ stateLabel }}</el-tag></dd><dt>首次预警时间</dt><dd>{{ date(alert.first_triggered_at) }}</dd><dt>最新预警时间</dt><dd>{{ date(alert.last_changed_at) }}</dd><dt>已读状态</dt><dd><span :class="alert.is_read?'read':'unread'">{{ alert.is_read ? '已读' : '未读' }}</span></dd><dt>状态依据</dt><dd>{{ stateBasis }}</dd></dl></article>
    </section>
    <section class="middle-grid"><article class="card threshold"><h2><i class="el-icon-set-up"/>预警阈值与建议补货</h2><div class="threshold-values"><span>最低库存<b>{{ number(alert.min_stock_snapshot) }} {{ unit }}</b></span><span>安全库存<b>{{ number(alert.safety_stock_snapshot) }} {{ unit }}</b></span><span>最高库存<b>{{ number(alert.max_stock_snapshot) }} {{ unit }}</b></span><span>建议补货<b>{{ number(alert.suggested_replenishment_qty_snapshot) }} {{ unit }}</b></span><span>可用库存<b class="safe">{{ number(alert.available_qty) }} {{ unit }}</b></span><span>缺口数量<b class="danger">{{ shortage }} {{ unit }}</b></span></div><div class="scale"><i class="red-zone"/><i class="orange-zone"/><i class="green-zone"/><em :style="pointerStyle"/><div><span>0</span><span>{{ number(alert.min_stock_snapshot) }}<small>最低库存</small></span><span>{{ number(alert.safety_stock_snapshot) }}<small>安全库存</small></span><span>{{ number(alert.max_stock_snapshot) }}<small>最高库存</small></span><span>可用库存({{ number(alert.available_qty) }})</span></div></div></article><article class="card handling"><h2><i class="el-icon-document"/>处置与采购需求</h2><dl><dt>预警来源</dt><dd>库存预警工作台</dd><dt>采购需求（草稿）</dt><dd><el-tag v-if="alert.purchase_request_id" size="mini" type="success">已生成</el-tag><span v-else>未生成</span></dd><dt>采购需求单号</dt><dd><el-button v-if="request.request_no" type="text" @click="openPurchaseRequest">{{ request.request_no }}</el-button><span v-else>-</span></dd><dt>处置说明</dt><dd>{{ handlingText }}</dd></dl></article></section>
    <section class="card history"><h2><i class="el-icon-time"/>状态变化历史</h2><el-table :data="histories" border size="small"><el-table-column label="时间" min-width="160"><template slot-scope="{row}">{{ date(row.occurred_at) }}</template></el-table-column><el-table-column label="原状态" min-width="110"><template slot-scope="{row}"><el-tag size="mini" :type="tag(historyOldStatus(row),historyOldSeverity(row))">{{ label(historyOldStatus(row),historyOldSeverity(row)) }}</el-tag></template></el-table-column><el-table-column label="新状态" min-width="110"><template slot-scope="{row}"><el-tag size="mini" :type="tag(historyStatus(row),historySeverity(row))">{{ label(historyStatus(row),historySeverity(row)) }}</el-tag></template></el-table-column><el-table-column label="预警等级" min-width="100"><template slot-scope="{row}">{{ severityLabel(historySeverity(row)) }}</template></el-table-column><el-table-column label="可用库存快照" min-width="130"><template slot-scope="{row}">{{ number(row.quantity_snapshot && row.quantity_snapshot.available) }} {{ unit }}</template></el-table-column><el-table-column label="变化原因" min-width="300"><template slot-scope="{row}">{{ historyReason(row) }}</template></el-table-column><el-table-column label="操作人" min-width="90"><template>系统</template></el-table-column></el-table><el-pagination v-if="historyTotal>historyPerPage" class="history-pager" background layout="prev, pager, next" :total="historyTotal" :page-size="historyPerPage" :current-page="historyPage" @current-change="loadHistory"/></section>
    <section class="card history"><h2><i class="el-icon-bell"/>通知与操作日志</h2><el-table :data="operationLogs" border size="small"><el-table-column label="时间" min-width="160"><template slot-scope="{row}">{{ date(row.time) }}</template></el-table-column><el-table-column label="类型" min-width="140"><template slot-scope="{row}">{{ row.type }}</template></el-table-column><el-table-column label="内容" min-width="520"><template slot-scope="{row}">{{ row.content }}</template></el-table-column><el-table-column label="操作人" min-width="90"><template slot-scope="{row}">{{ row.operator }}</template></el-table-column></el-table></section>
  </section>
</template>
<script>
import { getInventoryAlert, markInventoryAlertRead, createPurchaseRequestFromInventoryAlert } from '@/api/erp/inventory'
export default { name:'InventoryAlertDetail', data:()=>({loading:false,alert:{},item:{},warehouse:{},evaluation:{},histories:[],historyPage:1,historyPerPage:10,historyTotal:0}), computed:{unit(){const u=this.item.unit||{};return u.symbol||u.unit_name||'PCS'},request(){return this.alert.purchase_request||{}},tagType(){return this.tag(this.evaluation.status||this.alert.alert_status,this.evaluation.severity||this.alert.severity)},severityClass(){return this.tagType==='danger'?'danger':this.tagType==='warning'?'warning':'safe'},stateLabel(){return this.label(this.evaluation.status||this.alert.alert_status,this.evaluation.severity||this.alert.severity)},stateBasis(){const e=this.evaluation||{},a=this.number(this.alert.available_qty);if(e.basis==='available_lte_zero')return `可用库存 ${a} ${this.unit} ≤ 0`;if(e.basis==='available_lte_min')return `可用库存 ${a} ${this.unit} ≤ 最低库存 ${this.number(this.alert.min_stock_snapshot)} ${this.unit}`;if(e.basis==='available_lte_safety')return `可用库存 ${a} ${this.unit} ≤ 安全库存 ${this.number(this.alert.safety_stock_snapshot)} ${this.unit}`;if(e.basis==='available_gt_max')return `可用库存 ${a} ${this.unit} ＞ 最高库存 ${this.number(this.alert.max_stock_snapshot)} ${this.unit}`;return `可用库存 ${a} ${this.unit} ＞ 安全库存 ${this.number(this.alert.safety_stock_snapshot)} ${this.unit}`},shortage(){return Math.max(0,Number(this.alert.safety_stock_snapshot||0)-Number(this.alert.available_qty||0)).toFixed(0)},pointerStyle(){const max=Math.max(1,Number(this.alert.max_stock_snapshot||0));return {left:`${Math.min(100,Math.max(0,Number(this.alert.available_qty||0)/max*100))}%`}},purchaseAction(){return ['approved','converted','completed'].includes(this.request.request_status)?'查看采购进度':'查看采购需求'},handlingText(){return this.alert.purchase_request_id?`已生成采购需求 ${this.request.request_no||''}，请按采购流程审核处理。`:`建议补货 ${this.number(this.alert.suggested_replenishment_qty_snapshot)} ${this.unit}，以恢复到安全库存水平。`},operationLogs(){const logs=this.histories.map(row=>({time:row.occurred_at,type:'预警通知',content:`库存状态变更为${this.label(this.historyStatus(row),this.historySeverity(row))}：${this.historyReason(row)}`,operator:'系统'}));if(this.alert.purchase_request_id)logs.push({time:this.request.created_at||this.alert.updated_at,type:'采购需求生成',content:`基于库存预警生成采购需求（草稿）：${this.request.request_no||'-'}。`,operator:'当前用户'});return logs.sort((a,b)=>new Date(b.time)-new Date(a.time))}},created(){this.load()},methods:{async load(page){if(page)this.historyPage=page;this.loading=true;try{const r=await getInventoryAlert(this.$route.params.id,{per_page:this.historyPerPage,history_page:this.historyPage});this.alert=r.data.data||{};this.item=this.alert.item||{};this.warehouse=this.alert.warehouse||{};this.evaluation=r.data.evaluation||{};const h=r.data.histories||{};this.histories=h.data||[];this.historyTotal=h.total||0;this.historyPage=h.current_page||this.historyPage;if(!this.alert.is_read){await markInventoryAlertRead(this.alert.id);this.alert.is_read=true;window.dispatchEvent(new Event('erp:inventory-alert-read'))}}catch(e){this.$message.error(e.userMessage||'库存预警详情加载失败')}finally{this.loading=false}},loadHistory(page){this.load(page)},async createRequest(){try{const r=await createPurchaseRequestFromInventoryAlert(this.alert.id);this.alert.purchase_request_id=r.data.data.id;this.alert.purchase_request=r.data.data;this.$message.success('已生成采购需求草稿') }catch(e){this.$message.error(e.userMessage||'生成采购需求失败')}},openPurchaseRequest(){if(this.alert.purchase_request_id)this.$router.push(`/purchase/requests/${this.alert.purchase_request_id}/edit`)},number(v){return Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:6})},date(v){return v?String(v).replace('T',' ').replace('.000000Z',''): '-'},tag(status,severity){if(status==='out_of_stock'||severity==='critical')return 'danger';if(status==='low_stock')return 'warning';if(status==='over_stock')return 'info';return 'success'},label(status,severity){if(!status)return '-';if(status==='low_stock')return severity==='critical'?'低库存（严重）':'低库存（一般）';return ({out_of_stock:'缺货（严重）',over_stock:'超储',normal:'正常'})[status]||status},severityLabel(v){return ({critical:'严重',warning:'一般',info:'提示',normal:'正常'})[v]||'-'},historyOldStatus(row){return row.display_old_status===undefined?row.old_status:row.display_old_status},historyOldSeverity(row){return row.display_old_severity===undefined?row.old_severity:row.display_old_severity},historyStatus(row){return row.evaluation&&row.evaluation.status||row.new_status},historySeverity(row){return row.evaluation&&row.evaluation.severity||row.new_severity},historyReason(row){const s=(row.quantity_snapshot||{}).available;const status=this.historyStatus(row),severity=this.historySeverity(row);if(status==='out_of_stock')return `可用库存 ${this.number(s)} ${this.unit}，已无可用库存。`;if(status==='low_stock'&&severity==='critical')return `可用库存 ${this.number(s)} ${this.unit} ≤ 最低库存 ${this.number(this.alert.min_stock_snapshot)} ${this.unit}。`;if(status==='low_stock')return `可用库存 ${this.number(s)} ${this.unit} 已回升至最低库存以上，仍未超过安全库存。`;if(status==='normal')return `可用库存 ${this.number(s)} ${this.unit} 已超过安全库存。`;if(status==='over_stock')return `可用库存 ${this.number(s)} ${this.unit} ＞ 最高库存 ${this.number(this.alert.max_stock_snapshot)} ${this.unit}。`;return row.change_reason||'-'}}}
</script>
<style scoped>
.alert-detail{min-height:calc(100vh - 52px);padding:22px 24px 34px;background:#f7f9fb;color:#1e293b;box-sizing:border-box}.page-heading{display:flex;align-items:center;justify-content:space-between;margin:0 0 12px}.page-heading h1{margin:0;font-size:28px;color:#172033}.page-heading .el-button{height:36px;margin-left:10px}.page-heading .el-button--success{background:#07883f;border-color:#07883f}.alert-detail>.el-alert{margin-bottom:16px;border:1px solid #aaceff;background:#f2f8ff}.top-grid{display:grid;grid-template-columns:1fr 1.28fr 1.12fr;gap:14px;margin-bottom:14px}.middle-grid{display:grid;grid-template-columns:1.08fr 1fr;gap:14px;margin-bottom:14px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:7px;padding:14px 18px;box-sizing:border-box}.card h2{height:28px;margin:0 0 12px;padding-bottom:8px;border-bottom:1px solid #e8edf3;font-size:17px;line-height:20px;color:#172033}.card h2 i{display:inline-block;width:22px;height:22px;margin-right:7px;border-radius:6px;color:#fff;background:#0b8af0;text-align:center;line-height:22px;font-size:13px}.object h2 i{background:#ff5a5f}.facts h2 i{background:#ff9838}.state h2 i{background:#ff7c20}.threshold h2 i{background:#8969ff}.handling h2 i{background:#1684e8}.history h2 i{background:#128bf2;border-radius:50%}.card dl{display:grid;grid-template-columns:145px 1fr;gap:10px 12px;margin:0;font-size:14px;line-height:20px}.object dl{grid-template-columns:132px 1fr}.card dt{color:#475569}.card dd{margin:0;color:#1f2937}.facts-body{display:grid;grid-template-columns:1fr 178px;min-height:120px}.facts .facts-body dl{grid-template-columns:132px 1fr}.available{border-left:1px dashed #cbd5e1;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:12px}.available span{font-size:15px;color:#374151}.available strong{font-size:29px;line-height:34px}.available .danger{color:#ef1717}.available .warning{color:#f18700}.available .safe{color:#009a52}.read,.unread{font-size:14px}.read{color:#64748b}.unread{color:#1677ff}.unread:before{content:'●';font-size:11px;margin-right:6px}.threshold-values{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;margin:2px 0 16px}.threshold-values span{display:flex;flex-direction:column;gap:7px;font-size:13px;color:#475569}.threshold-values b{font-size:16px;color:#18202d;white-space:nowrap}.threshold-values .safe{color:#00a55b}.threshold-values .danger{color:#f31e1e}.scale{position:relative;padding-top:8px}.scale>i{display:inline-block;height:5px}.red-zone{width:20%;background:#f43f43;border-radius:3px 0 0 3px}.orange-zone{width:10%;background:#fb9b20}.green-zone{width:40%;background:#42c77c}.scale:after{content:'';position:absolute;top:8px;right:0;width:30%;height:5px;background:#e4e9ef;border-radius:0 3px 3px 0}.scale em{position:absolute;top:-3px;width:0;height:0;border-left:6px solid transparent;border-right:6px solid transparent;border-top:8px solid #0eb66a;transform:translateX(-50%);z-index:1}.scale>div{display:grid;grid-template-columns:20% 10% 40% 1fr;gap:0;margin-top:10px;font-size:12px;color:#374151}.scale span{position:relative;white-space:nowrap}.scale span:nth-child(2),.scale span:nth-child(3),.scale span:nth-child(4){text-align:center}.scale small{display:block;font-size:11px;color:#64748b}.handling dl{grid-template-columns:140px 1fr}.history{margin-bottom:14px;padding:13px 18px 16px}.history h2{margin-bottom:0}.history :deep(.el-table th){background:#f7f9fc;color:#465266}.history :deep(.el-table td),.history :deep(.el-table th){height:38px}.history-pager{padding-top:12px;text-align:right}@media(max-width:1200px){.top-grid{grid-template-columns:1fr 1fr}.state{grid-column:1/-1}.middle-grid{grid-template-columns:1fr}.threshold-values{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.alert-detail{padding:16px 12px}.page-heading{display:block}.page-heading>div{margin-top:10px}.page-heading .el-button{margin-left:0;margin-right:8px}.top-grid,.middle-grid{grid-template-columns:1fr}.state{grid-column:auto}.facts-body{grid-template-columns:1fr}.available{border-left:0;border-top:1px dashed #cbd5e1;margin-top:10px;padding-top:10px}.threshold-values{grid-template-columns:repeat(2,1fr)}.history{overflow-x:auto}.history .el-table{min-width:980px}.scale{min-width:610px;overflow:hidden}}
</style>
